using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// ── DI & services ──────────────────────────────────────────────────────────────
var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
services.AddChatClient(builder =>
    builder.UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// ── Tools ──────────────────────────────────────────────────────────────────────
var notebook = new ResearchNotebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            return WebSearchTool.SearchAsync(query);
        },
        "web_search",
        "Search the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("A concise title for the note")] string title,
         [Description("The note content with key facts")] string content) =>
        {
            notebook.Add(title, content);
            Console.WriteLine($"  📝 Note saved: \"{title}\"");
            return $"Note \"{title}\" saved successfully.";
        },
        "save_note",
        "Save a research note. Use this to record important findings during research."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = notebook.GetAll();
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select((n, i) => $"[{i + 1}] {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieve all saved research notes to review findings before writing a summary."),
};

// ── Agent setup ────────────────────────────────────────────────────────────────
const string completionMarker = "<<RESEARCH_COMPLETE>>";

var instructions = $"""
    You are a research agent. Given a topic, you must:
    1. Search the web for relevant information using multiple varied queries.
    2. Save important findings as notes using the save_note tool.
    3. After gathering enough information (at least 3 searches and 3 notes),
       review your notes with get_notes.
    4. Write a comprehensive summary of your findings.
    5. End your final message with exactly: {completionMarker}

    Be thorough but concise. Focus on facts, key details, and diverse perspectives.
    """;

var innerAgent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools,
    loggerFactory: loggerFactory);

var agent = new LoopAgent(
    innerAgent,
    new CompletionMarkerLoopEvaluator(new CompletionMarkerLoopEvaluatorOptions
    {
        CompletionMarker = completionMarker,
    }),
    new LoopAgentOptions { MaxIterations = 15 },
    loggerFactory);

// ── Run ────────────────────────────────────────────────────────────────────────
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║      🔬 AI Research Agent            ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.Write("\nEnter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: \"{topic}\"\n");

var response = await agent.RunAsync($"Research the following topic thoroughly: {topic}");

// Strip the completion marker from the displayed output
var summary = response.Text?.Replace(completionMarker, "").TrimEnd() ?? "No response generated.";

Console.WriteLine("\n══════════════════════════════════════");
Console.WriteLine("           📋 Research Summary");
Console.WriteLine("══════════════════════════════════════\n");
Console.WriteLine(summary);
Console.WriteLine("\n══════════════════════════════════════");
Console.WriteLine($"  Notes collected: {notebook.GetAll().Count}");
Console.WriteLine("══════════════════════════════════════");

// ── Supporting types ───────────────────────────────────────────────────────────

/// <summary>Simple in-memory notebook for storing research notes.</summary>
class ResearchNotebook
{
    private readonly List<Note> _notes = [];

    public void Add(string title, string content) =>
        _notes.Add(new Note(title, content));

    public IReadOnlyList<Note> GetAll() => _notes.AsReadOnly();

    public record Note(string Title, string Content);
}

/// <summary>Web search tool using Bing search via scraping for demo purposes.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await s_http.GetStringAsync(url);

            var results = ParseResults(html);
            if (results.Count == 0)
                return "No search results found.";

            return string.Join("\n\n", results.Take(5).Select((r, i) =>
                $"[{i + 1}] {r.Title}\n{r.Snippet}"));
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();
        var snippetTag = "class=\"result__snippet";
        var titleTag = "class=\"result__a";

        var pos = 0;
        while (pos < html.Length && results.Count < 5)
        {
            var titleStart = html.IndexOf(titleTag, pos, StringComparison.Ordinal);
            if (titleStart < 0) break;

            var title = ExtractTagContent(html, titleStart);
            var snippetStart = html.IndexOf(snippetTag, titleStart, StringComparison.Ordinal);
            var snippet = snippetStart >= 0 ? ExtractTagContent(html, snippetStart) : "";

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(CleanHtml(title), CleanHtml(snippet)));

            pos = snippetStart >= 0 ? snippetStart + 1 : titleStart + 1;
        }

        return results;
    }

    private static string ExtractTagContent(string html, int startFrom)
    {
        var gt = html.IndexOf('>', startFrom);
        if (gt < 0) return "";
        var closeTag = html.IndexOf('<', gt + 1);
        if (closeTag < 0) return "";
        return html[( gt + 1)..closeTag];
    }

    private static string CleanHtml(string text) =>
        System.Net.WebUtility.HtmlDecode(text).Trim();

    private record SearchResult(string Title, string Snippet);
}

