            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await s_http.GetStringAsync(url);

            var results = ParseResults(html);
            if (results.Count == 0)
                return "No search results found.";

            return string.Join("\n\n", results.Take(5).Select((r, i) =>
                $"[{i + 1}] {r.Title}\n{r.Snippet}"));
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();
        var snippetTag = "class=\"result__snippet";
        var titleTag = "class=\"result__a";

        var pos = 0;
        while (pos < html.Length && results.Count < 5)
        {
            var titleStart = html.IndexOf(titleTag, pos, StringComparison.Ordinal);
            if (titleStart < 0) break;

            var title = ExtractTagContent(html, titleStart);
            var snippetStart = html.IndexOf(snippetTag, titleStart, StringComparison.Ordinal);
            var snippet = snippetStart >= 0 ? ExtractTagContent(html, snippetStart) : "";

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(CleanHtml(title), CleanHtml(snippet)));

            pos = snippetStart >= 0 ? snippetStart + 1 : titleStart + 1;
        }

        return results;
    }

    private static string ExtractTagContent(string html, int startFrom)
    {
        var gt = html.IndexOf('>', startFrom);
        if (gt < 0) return "";
        var closeTag = html.IndexOf('<', gt + 1);
        if (closeTag < 0) return "";
        return html[( gt + 1)..closeTag];
    }

    private static string CleanHtml(string text) =>
        System.Net.WebUtility.HtmlDecode(text).Trim();

    private record SearchResult(string Title, string Snippet);
}

