     You are a research agent. Given a topic, you must:
     1. Search the web for relevant information using multiple varied queries.
     2. Save important findings as notes using the save_note tool.
     3. After gathering enough information (at least 3 searches and 3 notes),
        review your notes with get_notes.
     4. Write a comprehensive summary of your findings.
     5. End your final message with exactly: {completionMarker}

     Be thorough but concise. Focus on facts, key details, and diverse perspectives.
     """;

 var innerAgent = new ChatClientAgent(
     chatClient,
     instructions: instructions,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     tools: tools,
     loggerFactory: loggerFactory);

 #pragma warning disable MAAI001 // LoopAgent and evaluators are prerelease
 var agent = new LoopAgent(
     innerAgent,
     new CompletionMarkerLoopEvaluator(completionMarker),
     new LoopAgentOptions { MaxIterations = 15 },
     loggerFactory);
 #pragma warning restore MAAI001

 // ── Run ────────────────────────────────────────────────────────────────────────
 Console.WriteLine("╔══════════════════════════════════════╗");
 Console.WriteLine("║      🔬 AI Research Agent            ║");
 Console.WriteLine("╚══════════════════════════════════════╝");
 Console.Write("\nEnter a research topic: ");
 var topic = Console.ReadLine()?.Trim();
 if (string.IsNullOrWhiteSpace(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\nResearching: \"{topic}\"\n");

 var response = await agent.RunAsync($"Research the following topic thoroughly: {topic}");

 // Strip the completion marker from the displayed output
 var summary = response.Text?.Replace(completionMarker, "").TrimEnd() ?? "No response generated.";

 Console.WriteLine("\n══════════════════════════════════════");
 Console.WriteLine("           📋 Research Summary");
 Console.WriteLine("══════════════════════════════════════\n");
 Console.WriteLine(summary);
 Console.WriteLine("\n══════════════════════════════════════");
 Console.WriteLine($"  Notes collected: {notebook.GetAll().Count}");
 Console.WriteLine("══════════════════════════════════════");

